n = int(input())
arr = list(input().split())

def evl(c1, c2):
	return c1[0] == c2[0] or c1[1] == c2[1]
vt = set()
q = [arr[:]]
while q:
	ar = q.pop()
	vt.add(''.join(ar))
	if len(ar) > 3 and evl(ar[-1], ar[-4]):
		tmp = ar[:len(ar) - 1]
		tmp[-3] = ar[-1]
		if ''.join(tmp) not in vt:
			q.append(tmp)
	if len(ar) > 1 and evl(ar[-1], ar[-2]):
		tmp = ar[:len(ar) - 1]
		tmp[-1] = ar[-1]
		if len(tmp) == 1:
			print('YES')
			exit(0)
		elif ''.join(tmp) not in vt:
			q.append(tmp)
print('NO' if n > 1 else 'YES')
